<script setup lang="ts">
import {inject,ref,watch,nextTick,computed,onMounted,onUnmounted} from 'vue'
import AppIcon from './AppIcon.vue'
import {hitFigure} from './boxRuntime'
import {personState,instanceName} from './people'
const studio=inject<any>('studio',null)
const props=defineProps<{project:Record<string,any>,zoom:number,selectedId?:string,disabled?:boolean,mode?:string,proposals?:Record<string,any>[],showAnnotations?:boolean}>()
const emit=defineEmits(['select','changed','added','update:zoom'])
const hovered=ref(''),selected=ref(''),container=ref<HTMLElement|null>(null)
const canPanLeft=ref(false),canPanRight=ref(false)
// This bundled source is a screenshot with a baked-in footer, not original artwork.
// Clip its last 40 of 526 pixels without changing the image's annotation coordinates.
const screenshotFooter=computed(()=>/\/latest-project\.png(?:[?#]|$)/.test(props.project.image))
function updatePan(){const el=container.value;canPanLeft.value=!!el&&el.scrollLeft>1;canPanRight.value=!!el&&el.scrollLeft+el.clientWidth<el.scrollWidth-1}
function pan(direction:number){const el=container.value;if(el)el.scrollBy({left:direction*el.clientWidth*.55,behavior:'smooth'})}
function zoomBy(delta:number){emit('update:zoom',Math.max(50,Math.min(300,Number(props.zoom)+delta)))}
async function fit(){emit('update:zoom',100);await nextTick();container.value?.scrollTo({left:0,top:0});updatePan()}
watch(()=>props.zoom,async(value,old)=>{const el=container.value;if(!el)return;const x=(el.scrollLeft+el.clientWidth/2)/el.scrollWidth,y=(el.scrollTop+el.clientHeight/2)/el.scrollHeight;await nextTick();el.scrollLeft=x*el.scrollWidth-el.clientWidth/2;el.scrollTop=y*el.scrollHeight-el.clientHeight/2;updatePan()},{flush:'pre'})
let resizeObserver:ResizeObserver|undefined
onMounted(()=>{resizeObserver=new ResizeObserver(updatePan);if(container.value)resizeObserver.observe(container.value);updatePan()})
onUnmounted(()=>resizeObserver?.disconnect())

watch(()=>props.selectedId,async value=>{selected.value=value||'';await nextTick();const el=container.value?.querySelector(`[data-id="${selected.value}"]`);el?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})})
let drag:any=null
function hit(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect(),p=point(e);return hitFigure(props.project.annotations,p.x,p.y,r.width,r.height,selected.value,props.mode==='select')}
function point(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function down(e:PointerEvent){if(props.disabled)return;const start=point(e);const target=hit(e);selected.value=target?.id||'';emit('select',selected.value);const a=props.mode==='select'?props.project.annotations.find((a:any)=>a.id===selected.value):undefined;drag={start,a,before:a?{...a}:null,resize:!!target?.resize,clientX:e.clientX,clientY:e.clientY,left:container.value?.scrollLeft,top:container.value?.scrollTop};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(props.disabled)return;if(!drag){hovered.value=hit(e)?.id||'';return}if(props.mode==='pan'&&container.value){container.value.scrollLeft=drag.left-(e.clientX-drag.clientX);container.value.scrollTop=drag.top-(e.clientY-drag.clientY);return}if(!drag.a)return;const p=point(e),dx=p.x-drag.start.x,dy=p.y-drag.start.y;const a=drag.a,b=drag.before;if(drag.resize){a.w=Math.max(.005,Math.min(1-a.x,b.w+dx));a.h=Math.max(.005,Math.min(1-a.y,b.h+dy))}else{a.x=Math.max(0,Math.min(1-a.w,b.x+dx));a.y=Math.max(0,Math.min(1-a.h,b.y+dy))}a.confirmed=false;emit('changed',a.id)}
function up(e:PointerEvent){if(props.disabled){drag=null;return;}if(!drag)return;const p=point(e);if(props.mode==='add'&&!drag.a&&Math.abs(p.x-drag.start.x)>.01&&Math.abs(p.y-drag.start.y)>.01){const a={id:crypto.randomUUID().slice(0,12),x:Math.min(p.x,drag.start.x),y:Math.min(p.y,drag.start.y),w:Math.abs(p.x-drag.start.x),h:Math.abs(p.y-drag.start.y),description:'',kind:'character',characterId:'',confirmed:false};props.project.annotations.push(a);selected.value=a.id;emit('select',a.id);emit('added')}drag=null}
</script>
<template><div class="image-editor"><div ref="container" class="image-scroll" @scroll="updatePan"><div class="image-surface" :class="{'screenshot-crop':screenshotFooter}" :style="{width:zoom+'%'}"><div class="painting" :class="{'annotations-hidden':showAnnotations===false}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="drag=null" @pointerleave="hovered=''"><img :src="project.image" draggable="false"><div v-for="(a,i) in project.annotations" :data-id="a.id" class="editable-box" :class="[{selected:selected===a.id,hovered:hovered===a.id},personState(project,a,studio?.unit('visual:'+a.id)).key]" :style="{left:a.x*100+'%',top:a.y*100+'%',width:a.w*100+'%',height:a.h*100+'%'}"><span class="figure-box-name">{{instanceName(project,a)}} · {{personState(project,a,studio?.unit('visual:'+a.id)).label}}</span><span v-if="mode==='select'&&selected===a.id" class="resize"/></div><div v-for="(a,i) in proposals||[]" class="proposal-box" :style="{left:a.x*100+'%',top:a.y*100+'%',width:a.w*100+'%',height:a.h*100+'%'}"><span>补检 {{Number(i)+1}}</span></div></div></div></div><div class="painting-toolbar" role="toolbar" aria-label="画作视图调节"><span class="painting-view-hint">放大后可左右平移</span><div class="painting-view-buttons"><button type="button" :disabled="zoom>=300" aria-label="放大画作" title="放大" @click="zoomBy(10)"><AppIcon name="plus" :size="16"/><span>放大</span></button><button type="button" :disabled="zoom<=50" aria-label="缩小画作" title="缩小" @click="zoomBy(-10)"><AppIcon name="minus" :size="16"/><span>缩小</span></button><output aria-label="画作缩放比例">{{zoom}}%</output><button type="button" aria-label="适配页面" title="恢复完整画作并归位" @click="fit"><AppIcon name="fit" :size="16"/><span>适配页面</span></button><span class="view-divider"/><button type="button" :disabled="!canPanLeft" aria-label="向左平移" title="查看画作左侧" @click="pan(-1)"><AppIcon name="back" :size="16"/><span>左移</span></button><button type="button" :disabled="!canPanRight" aria-label="向右平移" title="查看画作右侧" @click="pan(1)"><AppIcon name="arrow" :size="16"/><span>右移</span></button></div></div></div></template>
<style scoped>
.image-editor{min-width:0}.image-surface{margin:0 auto}.image-surface.screenshot-crop{aspect-ratio:1180/486;overflow:hidden}.painting-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;background:#f7f6ee;border-top:1px solid #dce0d0;min-height:52px}.painting-view-hint{font-size:10px;color:#8b947e}.painting-view-buttons{display:flex;align-items:center;justify-content:center;gap:5px;flex-wrap:wrap}.painting-view-buttons button{padding:6px 8px;font-size:11px;min-height:30px;background:transparent;border:1px solid transparent;color:#42604e;border-radius:5px}.painting-view-buttons button:not(:disabled):hover{background:#e5ecda;border-color:#c8d5b9}.painting-view-buttons button:disabled{opacity:.3}.painting-view-buttons output{font-size:10px;min-width:38px;text-align:center;color:#839274;font-variant-numeric:tabular-nums}.view-divider{height:20px;width:1px;background:#d9ddcd;margin:0 4px}.painting-view-buttons :deep(svg){margin:0}.painting{width:100%}.painting>img{display:block;width:100%}.image-scroll{overscroll-behavior:contain;scrollbar-color:#a7b598 #eeeee2}
@media(max-width:1500px){.painting-view-hint{display:none}.painting-toolbar{justify-content:center}.painting-view-buttons button{padding:6px}}

.annotations-hidden .editable-box,.annotations-hidden .proposal-box{visibility:hidden}.figure-box-name{position:absolute;left:-1px;top:-1px;background:#94701ee8;color:#fffdf2;border:1px solid #f2e7c4;border-radius:2px;font:10px/1.6 "Microsoft YaHei",sans-serif;padding:2px 5px;white-space:nowrap;pointer-events:none;max-width:180px;overflow:hidden;text-overflow:ellipsis}.editable-box.confirmed .figure-box-name{background:#3b634fe8}.editable-box.selected .figure-box-name{background:#315e50}.proposal-box{position:absolute;border:1px dashed #387bb180;pointer-events:none;color:#fff;font-size:11px}.proposal-box>span{background:#387bb1;padding:2px 4px}.editable-box{position:absolute;border:1px solid #f5ecc48a;background:transparent!important;pointer-events:none;outline:none!important}.editable-box.confirmed{border-color:#2380524d}.editable-box.unnamed{border-color:#7c85834d}.editable-box.hovered{border-color:#387e70b3}.editable-box.selected{border:2px solid #f5e6b9;z-index:2}.box-label{position:absolute;z-index:5;white-space:nowrap;background:#31594be6;color:white;font-size:11px;padding:3px 7px;border-radius:4px;line-height:18px;pointer-events:none;max-width:22%;overflow:hidden;text-overflow:ellipsis}.resize{position:absolute;bottom:-4px;right:-4px;width:8px;height:8px;background:white;border:1px solid #406ec0;cursor:nwse-resize;pointer-events:auto}.image-scroll{max-height:650px;overflow:auto}.painting{cursor:crosshair}
</style>
